<?php require 'config.php'; $pageTitle='Sản phẩm'; $q=trim($_GET['q']??''); $cat=(int)($_GET['category']??0); $categories=$pdo->query('SELECT * FROM categories ORDER BY category_name')->fetchAll(); $sql='SELECT p.*,c.category_name FROM products p LEFT JOIN categories c ON p.category_id=c.category_id WHERE 1=1'; $params=[]; if($q!==''){$sql.=' AND p.product_name LIKE ?';$params[]="%$q%";} if($cat){$sql.=' AND p.category_id=?';$params[]=$cat;} $sql.=' ORDER BY p.product_id DESC'; $st=$pdo->prepare($sql);$st->execute($params);$products=$st->fetchAll(); require 'includes/header.php'; ?>
<h1 class="section-title">Tất cả sản phẩm</h1><form class="row g-2 mb-4" method="get"><div class="col-md-6"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Tìm bàn phím, chuột, tai nghe..."></div><div class="col-md-4"><select class="form-select" name="category"><option value="0">Tất cả danh mục</option><?php foreach($categories as $c): ?><option value="<?= $c['category_id'] ?>" <?= $cat===$c['category_id']?'selected':'' ?>><?= e($c['category_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2 d-grid"><button class="btn btn-red">Tìm kiếm</button></div></form><div class="row g-4"><?php foreach($products as $p): ?><div class="col-6 col-md-4 col-lg-3"><div class="card product-card"><img class="product-img" src="<?= e($p['image'] ?: 'https://placehold.co/600x400?text=GameGear') ?>" alt="<?= e($p['product_name']) ?>"><div class="card-body d-flex flex-column"><div class="small-muted"><?= e($p['category_name']??'Phụ kiện') ?> · Còn <?= (int)$p['quantity'] ?></div><h5 class="fs-6 mt-2"><?= e($p['product_name']) ?></h5><div class="price mt-auto mb-3"><?= money($p['price']) ?></div><a class="btn btn-outline-dark btn-sm" href="product.php?id=<?= (int)$p['product_id'] ?>">Xem chi tiết</a></div></div></div><?php endforeach; ?><?php if(!$products): ?><p>Không tìm thấy sản phẩm phù hợp.</p><?php endif; ?></div><?php require 'includes/footer.php'; ?>
